param([string]$IcarusRoot = $(if ($env:IVERILOG_ROOT) { $env:IVERILOG_ROOT } else { 'D:\Tools\iverilog-v12' }))
$ErrorActionPreference='Stop';$env:PATH="$(Resolve-Path $IcarusRoot)\bin;"+$env:PATH;New-Item -ItemType Directory -Force tmp/mes50hp_pipeline_soc|Out-Null
$src=@('rtl/pipeline_cpu.v','rtl/branch_predictor.v','rtl/forward_unit.v','rtl/hazard_unit.v','rtl/perf_monitor.v','rtl/perf_mmio.v','rtl/regfile.v','rtl/alu.v','rtl/imm_gen.v','rtl/decoder.v','rtl/branch_unit.v','rtl/load_store_unit.v','rtl/soc_data_interconnect.v','rtl/soc_fpga_memory.v','rtl/uart_tx.v','rtl/uart_rx.v','rtl/uart_mmio.v','rtl/gpio_mmio.v','fpga/pipeline_soc/rtl/mes50hp_pipeline_soc_top.v','tb/tb_mes50hp_pipeline_soc.v')
iverilog -g2012 -s tb_mes50hp_pipeline_soc -o tmp/mes50hp_pipeline_soc/tb @src;if($LASTEXITCODE-ne0){exit $LASTEXITCODE};vvp tmp/mes50hp_pipeline_soc/tb;exit $LASTEXITCODE
